{"question_id": 28, "sql": "SELECT T2.School, T2.DOC FROM frpm AS T1 JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode WHERE T2.FundingType = 'Locally funded' AND T1.`Enrollment (K-12)` - T1.`Enrollment (Ages 5-17)` > (SELECT AVG(f2.`Enrollment (K-12)` - f2.`Enrollment (Ages 5-17)`) FROM frpm AS f2 JOIN schools AS s2 ON f2.CDSCode = s2.CDSCode WHERE s2.FundingType = 'Locally funded')"}
{"question_id": 36, "sql": "SELECT T2.AdmFName1, T2.AdmLName1, T2.AdmFName2, T2.AdmLName2, T2.AdmFName3, T2.AdmLName3 FROM satscores AS T1 JOIN schools AS T2 ON T1.cds = T2.CDSCode WHERE T1.NumGE1500 = (SELECT MAX(NumGE1500) FROM satscores)"}
{"question_id": 62, "sql": "SELECT COUNT(*) FROM frpm AS T1 JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode WHERE T2.County = 'Los Angeles' AND T2.Charter = 0 AND T1.`Free Meal Count (K-12)` * 100 / T1.`Enrollment (K-12)` < 0.18"}
{"question_id": 83, "sql": "SELECT T2.City, COUNT(*) FROM frpm AS T1 JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode WHERE T2.Magnet = 1 AND T2.GSoffered = 'K-8' AND T1.`NSLP Provision Status` = 'Multiple Provision Types' GROUP BY T2.City"}
{"question_id": 87, "sql": "SELECT AdmEmail1, AdmEmail2 FROM schools WHERE County = 'San Bernardino' AND City = 'San Bernardino' AND DOC = '54' AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31' AND SOC = '62'"}
{"question_id": 12, "sql": "SELECT MAX(1.0 * T2.`Free Meal Count (Ages 5-17)` / T2.`Enrollment (Ages 5-17)`) AS max_ratio FROM satscores AS T1 JOIN frpm AS T2 ON T1.cds = T2.CDSCode WHERE 1.0 * T1.NumGE1500 / T1.NumTstTakr > 0.3"}
{"question_id": 23, "sql": "SELECT T2.School, T2.Street FROM frpm AS T1 JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode WHERE T1.`Enrollment (K-12)` - T1.`Enrollment (Ages 5-17)` > 30"}
{"question_id": 24, "sql": "SELECT T1.`School Name` FROM frpm AS T1 JOIN satscores AS T2 ON T1.CDSCode = T2.cds WHERE 1.0 * T1.`Free Meal Count (K-12)` / T1.`Enrollment (K-12)` > 0.1 AND T2.NumGE1500 > 0"}
{"question_id": 25, "sql": "SELECT s.sname, f.`Charter Funding Type` FROM satscores AS s JOIN frpm AS f ON s.cds = f.CDSCode WHERE f.`District Name` LIKE 'Riverside%' AND (SELECT SUM(s2.AvgScrMath) / COUNT(*) FROM satscores AS s2 JOIN frpm AS f2 ON s2.cds = f2.CDSCode WHERE f2.`District Name` LIKE 'Riverside%') > 400"}
{"question_id": 26, "sql": "SELECT T1.`School Name`, T2.Street, T2.City, T2.State, T2.Zip FROM frpm AS T1 JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode WHERE T1.`County Name` = 'Monterey' AND T1.`School Type` = 'High Schools (Public)' AND T1.`FRPM Count (Ages 5-17)` > 800"}
{"question_id": 27, "sql": "SELECT T1.School, T2.AvgScrWrite, T1.Phone FROM schools AS T1 LEFT JOIN satscores AS T2 ON T1.CDSCode = T2.cds WHERE T1.OpenDate > '1991-12-31' OR T1.ClosedDate < '2000-01-01'"}
{"question_id": 31, "sql": "SELECT 1.0 * `Free Meal Count (K-12)` / `Enrollment (K-12)` AS ratio FROM frpm ORDER BY `Enrollment (K-12)` DESC LIMIT 2 OFFSET 9"}
{"question_id": 5, "sql": "SELECT COUNT(*) FROM schools AS T1 JOIN satscores AS T2 ON T1.CDSCode = T2.cds WHERE T2.AvgScrMath > 400 AND T1.Virtual = 'F'"}
{"question_id": 11, "sql": "SELECT CDSCode FROM frpm WHERE `Enrollment (K-12)` + `Enrollment (Ages 5-17)` > 500"}
{"question_id": 17, "sql": "SELECT T1.CharterNum, T2.AvgScrWrite, RANK() OVER (ORDER BY T2.AvgScrWrite DESC) AS WritingScoreRank FROM schools AS T1 JOIN satscores AS T2 ON T1.CDSCode = T2.cds WHERE T2.AvgScrWrite > 499 AND T1.CharterNum IS NOT NULL"}
